    (N'B0000000-0000-0000-0000-000000000278', 2, N'Say in Italian that you have a reservation under your name.', N'Ho una prenotazione a nome mio.', 1, N'Wikipedia: Italian phrasebook', 0, 45, N'A0000000-0000-0000-0000-000000000006', 28, '2026-01-18T09:00:00', 0, NULL),
