    (N'B0000000-0000-0000-0000-000000000296', 1, N'Record yourself checking into a hotel in Italian and listen back.', NULL, 1, N'Wikipedia: Italian phrasebook', 0, 240, N'A0000000-0000-0000-0000-000000000006', 46, '2026-01-18T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000297', 1, N'Read the departures board of an Italian airport online and explain three entries aloud.', NULL, 1, N'Wikipedia: Italian phrasebook', 0, 300, N'A0000000-0000-0000-0000-000000000006', 47, '2026-01-18T09:00:00', 0, NULL),
