    (N'B0000000-0000-0000-0000-000000000451', 4, N'Which clause selects which columns are returned?', NULL, 1, N'Wikipedia: SQL', 0, 20, N'A0000000-0000-0000-0000-000000000010', 1, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000452', 4, N'Which clause names the table to read from?', NULL, 1, N'Wikipedia: SQL', 0, 25, N'A0000000-0000-0000-0000-000000000010', 2, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000453', 4, N'Which clause filters rows before grouping?', NULL, 1, NULL, 0, 30, N'A0000000-0000-0000-0000-000000000010', 3, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000454', 4, N'Which clause filters groups after aggregation?', NULL, 1, N'Wikipedia: SQL', 0, 15, N'A0000000-0000-0000-0000-000000000010', 4, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000455', 4, N'Which clause sorts the result?', NULL, 1, N'Wikipedia: SQL', 0, 20, N'A0000000-0000-0000-0000-000000000010', 5, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000456', 4, N'Which clause collapses rows into groups?', NULL, 1, NULL, 0, 25, N'A0000000-0000-0000-0000-000000000010', 6, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000457', 4, N'Which keyword removes duplicate rows from a result?', NULL, 1, N'Wikipedia: SQL', 0, 30, N'A0000000-0000-0000-0000-000000000010', 7, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000458', 4, N'Which keyword adds new rows to a table?', NULL, 1, N'Wikipedia: SQL', 0, 15, N'A0000000-0000-0000-0000-000000000010', 8, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000459', 4, N'Which keyword changes existing rows?', NULL, 1, NULL, 0, 20, N'A0000000-0000-0000-0000-000000000010', 9, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000460', 4, N'Which keyword removes rows from a table?', NULL, 1, N'Wikipedia: SQL', 0, 25, N'A0000000-0000-0000-0000-000000000010', 10, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000461', 4, N'Which statement removes every row quickly without logging each one?', NULL, 1, N'Wikipedia: SQL', 0, 30, N'A0000000-0000-0000-0000-000000000010', 11, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000462', 4, N'Which join returns only rows matching in both tables?', NULL, 1, NULL, 0, 15, N'A0000000-0000-0000-0000-000000000010', 12, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000463', 4, N'Which join keeps every row of the left table?', NULL, 1, N'Wikipedia: SQL', 1, 20, N'A0000000-0000-0000-0000-000000000010', 13, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000464', 4, N'Which join returns every combination of rows?', NULL, 1, N'Wikipedia: SQL', 0, 25, N'A0000000-0000-0000-0000-000000000010', 14, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000465', 4, N'Which aggregate function counts rows?', NULL, 1, NULL, 0, 30, N'A0000000-0000-0000-0000-000000000010', 15, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000466', 4, N'Which aggregate function adds values?', NULL, 1, N'Wikipedia: SQL', 0, 15, N'A0000000-0000-0000-0000-000000000010', 16, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000467', 4, N'Which aggregate function returns the arithmetic mean?', NULL, 0, N'Wikipedia: SQL', 0, 20, N'A0000000-0000-0000-0000-000000000010', 17, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000468', 4, N'Which operator tests whether a value is inside a list?', NULL, 1, NULL, 0, 25, N'A0000000-0000-0000-0000-000000000010', 18, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000469', 4, N'Which operator matches a text pattern?', NULL, 1, N'Wikipedia: SQL', 0, 30, N'A0000000-0000-0000-0000-000000000010', 19, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000470', 4, N'Which operator tests for a value in a range?', NULL, 1, N'Wikipedia: SQL', 0, 15, N'A0000000-0000-0000-0000-000000000010', 20, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000471', 4, N'How do you test that a column has no value?', NULL, 1, NULL, 0, 20, N'A0000000-0000-0000-0000-000000000010', 21, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000472', 4, N'Which function returns the first non-null argument?', NULL, 1, N'Wikipedia: SQL', 0, 25, N'A0000000-0000-0000-0000-000000000010', 22, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000473', 4, N'Which keyword limits the number of rows in SQL Server?', NULL, 1, N'Wikipedia: SQL', 0, 30, N'A0000000-0000-0000-0000-000000000010', 23, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000474', 4, N'Which statement adds a column to an existing table?', NULL, 1, NULL, 0, 15, N'A0000000-0000-0000-0000-000000000010', 24, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000475', 4, N'Which statement gives a permission to a user?', NULL, 1, N'Wikipedia: SQL', 0, 20, N'A0000000-0000-0000-0000-000000000010', 25, '2026-01-22T09:00:00', 1, '2026-07-16T09:00:00'),
    (N'B0000000-0000-0000-0000-000000000476', 2, N'Explain the logical order in which the clauses of a SELECT are evaluated.', N'FROM, then WHERE, then GROUP BY, then HAVING, then SELECT, then ORDER BY - which is why an alias from SELECT cannot be used in WHERE.', 1, N'Wikipedia: SQL', 1, 75, N'A0000000-0000-0000-0000-000000000010', 26, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000477', 2, N'Explain the difference between WHERE and HAVING.', N'WHERE filters individual rows before grouping; HAVING filters the groups that grouping produced.', 1, NULL, 0, 90, N'A0000000-0000-0000-0000-000000000010', 27, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000478', 2, N'Explain what NULL means in SQL and why it needs its own comparison.', N'It means unknown, so any comparison with it is unknown rather than true or false, which is why IS NULL exists.', 1, N'Wikipedia: SQL', 0, 45, N'A0000000-0000-0000-0000-000000000010', 28, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000479', 2, N'Explain the difference between an inner join and a left join, with an example.', N'An inner join drops customers with no orders; a left join keeps them, filling the order columns with nulls.', 1, N'Wikipedia: SQL', 0, 60, N'A0000000-0000-0000-0000-000000000010', 29, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000480', 2, N'Explain what an index is and what it costs.', N'A sorted structure that lets the engine find rows without scanning the table, paid for with storage and slower writes.', 1, NULL, 0, 75, N'A0000000-0000-0000-0000-000000000010', 30, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000481', 2, N'Explain what a primary key guarantees.', N'That the column or set of columns is unique and never null, so every row can be identified.', 1, N'Wikipedia: SQL', 0, 90, N'A0000000-0000-0000-0000-000000000010', 31, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000482', 2, N'Explain what a foreign key enforces.', N'That a value in one table exists as a key in another, so references cannot dangle.', 1, N'Wikipedia: SQL', 0, 45, N'A0000000-0000-0000-0000-000000000010', 32, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000483', 2, N'Explain what a transaction is and what the letters of ACID stand for.', N'A unit of work that succeeds or fails as a whole - atomicity, consistency, isolation and durability.', 1, NULL, 0, 60, N'A0000000-0000-0000-0000-000000000010', 33, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000484', 2, N'Explain the difference between UNION and UNION ALL.', N'UNION removes duplicate rows and therefore sorts; UNION ALL simply concatenates and is faster.', 0, N'Wikipedia: SQL', 0, 75, N'A0000000-0000-0000-0000-000000000010', 34, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000485', 2, N'Explain why SELECT * is discouraged in application code.', N'It moves more data than needed and breaks silently when the table''s columns change.', 1, N'Wikipedia: SQL', 0, 90, N'A0000000-0000-0000-0000-000000000010', 35, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000486', 3, N'What does a self join do, and give a case where you need one?', N'A table is joined to itself under two aliases, for example to pair employees with their managers.', 1, NULL, 0, 75, N'A0000000-0000-0000-0000-000000000010', 36, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000487', 3, N'What is a common table expression and how is it introduced?', N'A named temporary result defined before the query with WITH, which makes long queries readable and allows recursion.', 1, N'Wikipedia: SQL', 0, 90, N'A0000000-0000-0000-0000-000000000010', 37, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000488', 3, N'What does the OVER clause turn a function into?', N'A window function, which computes across a set of rows without collapsing them into one.', 1, N'Wikipedia: SQL', 0, 105, N'A0000000-0000-0000-0000-000000000010', 38, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000489', 3, N'What does ROW_NUMBER do, and how does it differ from RANK?', N'It numbers rows inside a partition with no ties; RANK gives equal values the same number and leaves gaps.', 1, NULL, 1, 120, N'A0000000-0000-0000-0000-000000000010', 39, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000490', 3, N'What is the difference between DELETE and TRUNCATE?', N'DELETE removes rows one by one and can be filtered; TRUNCATE drops all rows as a whole and resets identity values.', 1, N'Wikipedia: SQL', 0, 60, N'A0000000-0000-0000-0000-000000000010', 40, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000491', 3, N'What does a UNIQUE constraint allow that a primary key does not?', N'A null value, and a table may have many unique constraints but only one primary key.', 1, N'Wikipedia: SQL', 0, 75, N'A0000000-0000-0000-0000-000000000010', 41, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000492', 3, N'What is a clustered index, and how many can a table have?', N'It defines the physical order of the rows, so a table can have only one.', 1, NULL, 0, 90, N'A0000000-0000-0000-0000-000000000010', 42, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000493', 3, N'What is a deadlock and how does the engine resolve it?', N'Two transactions each hold what the other needs; the engine kills one as the victim and rolls it back.', 1, N'Wikipedia: SQL', 0, 105, N'A0000000-0000-0000-0000-000000000010', 43, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000494', 3, N'What does EXPLAIN or an execution plan show you?', N'How the engine intends to run the query - which indexes, joins and scans it will use, and their estimated cost.', 1, N'Wikipedia: SQL', 0, 120, N'A0000000-0000-0000-0000-000000000010', 44, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000495', 1, N'Write a query joining three tables in a database you know, then read its execution plan.', NULL, 1, NULL, 0, 180, N'A0000000-0000-0000-0000-000000000010', 45, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000496', 1, N'Take a slow query and add an index, then compare the plan before and after.', NULL, 1, N'Wikipedia: SQL', 0, 240, N'A0000000-0000-0000-0000-000000000010', 46, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000497', 1, N'Rewrite a query that uses a subquery so that it uses a join instead.', NULL, 1, N'Wikipedia: SQL', 0, 300, N'A0000000-0000-0000-0000-000000000010', 47, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000498', 1, N'Write a recursive common table expression that walks a parent-child table.', NULL, 1, NULL, 0, 360, N'A0000000-0000-0000-0000-000000000010', 48, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000499', 1, N'Fill a table with a million rows and time the same query with and without an index.', NULL, 1, N'Wikipedia: SQL', 0, 420, N'A0000000-0000-0000-0000-000000000010', 49, '2026-01-22T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000500', 1, N'Explain to a colleague, out loud, what a transaction isolation level changes.', NULL, 1, N'Wikipedia: SQL', 0, 180, N'A0000000-0000-0000-0000-000000000010', 50, '2026-01-22T09:00:00', 1, '2026-07-16T09:00:00');

