    (N'B0000000-0000-0000-0000-000000000916', 4, N'Which organ produces insulin?', NULL, 1, N'Gray''s Anatomy, introductory chapters', 0, 15, N'A0000000-0000-0000-0000-000000000019', 16, '2026-01-31T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000000917', 4, N'Which organ exchanges oxygen and carbon dioxide?', NULL, 0, N'Gray''s Anatomy, introductory chapters', 0, 20, N'A0000000-0000-0000-0000-000000000019', 17, '2026-01-31T09:00:00', 0, NULL),
