    (N'B0000000-0000-0000-0000-000000001163', 4, N'Which data structure gives the smallest element quickly?', NULL, 1, N'Introduction to Algorithms, chapters 1 to 8', 1, 20, N'A0000000-0000-0000-0000-000000000024', 13, '2026-02-05T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001164', 4, N'Which algorithm finds the shortest path with non-negative weights?', NULL, 1, N'Introduction to Algorithms, chapters 1 to 8', 0, 25, N'A0000000-0000-0000-0000-000000000024', 14, '2026-02-05T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001165', 4, N'Which algorithm finds shortest paths that may have negative weights?', NULL, 1, NULL, 0, 30, N'A0000000-0000-0000-0000-000000000024', 15, '2026-02-05T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001166', 4, N'Which traversal visits a tree level by level?', NULL, 1, N'Introduction to Algorithms, chapters 1 to 8', 0, 15, N'A0000000-0000-0000-0000-000000000024', 16, '2026-02-05T09:00:00', 0, NULL),
