    (N'B0000000-0000-0000-0000-000000001202', 4, N'Which black bird with a yellow bill is common in gardens?', NULL, 1, N'Collins Bird Guide', 0, 25, N'A0000000-0000-0000-0000-000000000025', 2, '2026-02-06T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001203', 4, N'Which red-breasted bird is a familiar garden visitor in Britain?', NULL, 1, NULL, 0, 30, N'A0000000-0000-0000-0000-000000000025', 3, '2026-02-06T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001204', 4, N'Which bird is known for laying its eggs in other birds'' nests?', NULL, 1, N'Collins Bird Guide', 0, 15, N'A0000000-0000-0000-0000-000000000025', 4, '2026-02-06T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001205', 4, N'Which bird of prey hovers over roadsides looking for voles?', NULL, 1, N'Collins Bird Guide', 0, 20, N'A0000000-0000-0000-0000-000000000025', 5, '2026-02-06T09:00:00', 0, NULL),
