    (N'B0000000-0000-0000-0000-000000001651', 4, N'Who composed the Brandenburg Concertos?', NULL, 1, N'The Oxford Companion to Music', 0, 20, N'A0000000-0000-0000-0000-000000000034', 1, '2026-02-15T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001652', 4, N'Who composed The Magic Flute?', NULL, 1, N'The Oxford Companion to Music', 0, 25, N'A0000000-0000-0000-0000-000000000034', 2, '2026-02-15T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001653', 4, N'Who composed the Ninth Symphony with a choral finale?', NULL, 1, NULL, 0, 30, N'A0000000-0000-0000-0000-000000000034', 3, '2026-02-15T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001654', 4, N'Who composed The Four Seasons?', NULL, 1, N'The Oxford Companion to Music', 0, 15, N'A0000000-0000-0000-0000-000000000034', 4, '2026-02-15T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001655', 4, N'Who composed Messiah?', NULL, 1, N'The Oxford Companion to Music', 0, 20, N'A0000000-0000-0000-0000-000000000034', 5, '2026-02-15T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001656', 4, N'Who composed the Nutcracker ballet?', NULL, 1, NULL, 0, 25, N'A0000000-0000-0000-0000-000000000034', 6, '2026-02-15T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001657', 4, N'Who composed The Rite of Spring?', NULL, 1, N'The Oxford Companion to Music', 0, 30, N'A0000000-0000-0000-0000-000000000034', 7, '2026-02-15T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001658', 4, N'Who composed Clair de lune?', NULL, 1, N'The Oxford Companion to Music', 0, 15, N'A0000000-0000-0000-0000-000000000034', 8, '2026-02-15T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001659', 4, N'Who composed Bolero?', NULL, 1, NULL, 0, 20, N'A0000000-0000-0000-0000-000000000034', 9, '2026-02-15T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001660', 4, N'Who composed the opera Carmen?', NULL, 1, N'The Oxford Companion to Music', 0, 25, N'A0000000-0000-0000-0000-000000000034', 10, '2026-02-15T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001661', 4, N'Who composed the opera La traviata?', NULL, 1, N'The Oxford Companion to Music', 0, 30, N'A0000000-0000-0000-0000-000000000034', 11, '2026-02-15T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000001662', 4, N'Who composed the opera Tosca?', NULL, 1, NULL, 0, 15, N'A0000000-0000-0000-0000-000000000034', 12, '2026-02-15T09:00:00', 0, NULL),
