VALUES
    (N'B0000000-0000-0000-0000-000000002301', 4, N'How many squares are on a chessboard?', NULL, 1, N'FIDE Laws of Chess', 0, 20, N'A0000000-0000-0000-0000-000000000047', 1, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002302', 4, N'How many pieces does each player start with?', NULL, 1, N'FIDE Laws of Chess', 0, 25, N'A0000000-0000-0000-0000-000000000047', 2, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002303', 4, N'How many pawns does each player start with?', NULL, 1, NULL, 0, 30, N'A0000000-0000-0000-0000-000000000047', 3, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002304', 4, N'How does a knight move?', NULL, 1, N'FIDE Laws of Chess', 0, 15, N'A0000000-0000-0000-0000-000000000047', 4, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002305', 4, N'How does a bishop move?', NULL, 1, N'FIDE Laws of Chess', 0, 20, N'A0000000-0000-0000-0000-000000000047', 5, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002306', 4, N'How does a rook move?', NULL, 1, NULL, 0, 25, N'A0000000-0000-0000-0000-000000000047', 6, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002307', 4, N'How does the queen move?', NULL, 1, N'FIDE Laws of Chess', 0, 30, N'A0000000-0000-0000-0000-000000000047', 7, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002308', 4, N'How far can a king move in one turn?', NULL, 1, N'FIDE Laws of Chess', 0, 15, N'A0000000-0000-0000-0000-000000000047', 8, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002309', 4, N'Which piece can jump over others?', NULL, 1, NULL, 0, 20, N'A0000000-0000-0000-0000-000000000047', 9, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002310', 4, N'What is the move that repositions king and rook called?', NULL, 1, N'FIDE Laws of Chess', 0, 25, N'A0000000-0000-0000-0000-000000000047', 10, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002311', 4, N'What is the pawn capture in passing called?', NULL, 1, N'FIDE Laws of Chess', 0, 30, N'A0000000-0000-0000-0000-000000000047', 11, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002312', 4, N'What is it called when a pawn reaches the far rank?', NULL, 1, NULL, 0, 15, N'A0000000-0000-0000-0000-000000000047', 12, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002313', 4, N'What is the position where the king is attacked called?', NULL, 1, N'FIDE Laws of Chess', 1, 20, N'A0000000-0000-0000-0000-000000000047', 13, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002314', 4, N'What is the position where the king is attacked and cannot escape called?', NULL, 1, N'FIDE Laws of Chess', 0, 25, N'A0000000-0000-0000-0000-000000000047', 14, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002315', 4, N'What is the position where a player has no legal move but is not in check called?', NULL, 1, NULL, 0, 30, N'A0000000-0000-0000-0000-000000000047', 15, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002316', 4, N'What is the value of a pawn in the usual counting?', NULL, 1, N'FIDE Laws of Chess', 0, 15, N'A0000000-0000-0000-0000-000000000047', 16, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002317', 4, N'What is the value of a knight or bishop in the usual counting?', NULL, 0, N'FIDE Laws of Chess', 0, 20, N'A0000000-0000-0000-0000-000000000047', 17, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002318', 4, N'What is the value of a rook?', NULL, 1, NULL, 0, 25, N'A0000000-0000-0000-0000-000000000047', 18, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002319', 4, N'What is the value of a queen?', NULL, 1, N'FIDE Laws of Chess', 0, 30, N'A0000000-0000-0000-0000-000000000047', 19, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002320', 4, N'Which square must be light for the board to be set correctly?', NULL, 1, N'FIDE Laws of Chess', 0, 15, N'A0000000-0000-0000-0000-000000000047', 20, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002321', 4, N'Which piece stands on the same colour as its own side''s queen at the start?', NULL, 1, NULL, 0, 20, N'A0000000-0000-0000-0000-000000000047', 21, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002322', 4, N'What is the opening move e4 called in general terms?', NULL, 1, N'FIDE Laws of Chess', 0, 25, N'A0000000-0000-0000-0000-000000000047', 22, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002323', 4, N'What is the opening 1.d4 d5 2.c4 called?', NULL, 1, N'FIDE Laws of Chess', 0, 30, N'A0000000-0000-0000-0000-000000000047', 23, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002324', 4, N'What is the opening 1.e4 c5 called?', NULL, 1, NULL, 0, 15, N'A0000000-0000-0000-0000-000000000047', 24, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002325', 4, N'What is the opening 1.e4 e5 2.Nf3 Nc6 3.Bb5 called?', NULL, 1, N'FIDE Laws of Chess', 0, 20, N'A0000000-0000-0000-0000-000000000047', 25, '2026-02-28T09:00:00', 1, '2026-07-13T09:00:00'),
    (N'B0000000-0000-0000-0000-000000002326', 2, N'Explain the three phases of a chess game and what each is about.', N'The opening develops pieces and fights for the centre, the middlegame is about plans and tactics, the endgame is about pawns, king activity and promotion.', 1, N'FIDE Laws of Chess', 1, 75, N'A0000000-0000-0000-0000-000000000047', 26, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002327', 2, N'Explain what castling requires.', N'Neither king nor rook has moved, the squares between are empty, and the king is not in check nor passes through or lands on an attacked square.', 1, NULL, 0, 90, N'A0000000-0000-0000-0000-000000000047', 27, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002328', 2, N'Explain what en passant is and when it can be played.', N'A pawn moving two squares past an enemy pawn may be captured as if it had moved one, but only on the very next move.', 1, N'FIDE Laws of Chess', 0, 45, N'A0000000-0000-0000-0000-000000000047', 28, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002329', 2, N'Explain the difference between a pin and a skewer.', N'A pin holds a piece in place because a more valuable one is behind it; a skewer attacks the valuable one first so it must move and expose the lesser.', 1, N'FIDE Laws of Chess', 0, 60, N'A0000000-0000-0000-0000-000000000047', 29, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002330', 2, N'Explain what a fork is.', N'One piece attacking two or more enemy pieces at once, so at least one must fall.', 1, NULL, 0, 75, N'A0000000-0000-0000-0000-000000000047', 30, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002331', 2, N'Explain what a discovered attack is.', N'Moving one piece uncovers an attack from another behind it, so two threats appear in one move.', 1, N'FIDE Laws of Chess', 0, 90, N'A0000000-0000-0000-0000-000000000047', 31, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002332', 2, N'Explain why control of the centre matters.', N'Pieces command more squares from the middle and can be redeployed to either wing faster.', 1, N'FIDE Laws of Chess', 0, 45, N'A0000000-0000-0000-0000-000000000047', 32, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002333', 2, N'Explain what a passed pawn is and why it is valuable.', N'A pawn with no enemy pawn ahead of it on its file or the adjacent ones, so it can run for promotion.', 1, NULL, 0, 60, N'A0000000-0000-0000-0000-000000000047', 33, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002334', 2, N'Explain the difference between a draw by stalemate, by repetition and by the fifty-move rule.', N'Stalemate is no legal move without check; repetition is the same position three times; fifty moves without a capture or pawn move also draws.', 0, N'FIDE Laws of Chess', 0, 75, N'A0000000-0000-0000-0000-000000000047', 34, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002335', 2, N'Explain what zugzwang is.', N'A position where any move a player makes worsens their position, but they are obliged to move.', 1, N'FIDE Laws of Chess', 0, 90, N'A0000000-0000-0000-0000-000000000047', 35, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002336', 3, N'What is the value of each piece in the usual counting, from pawn to queen?', N'Pawn one, knight and bishop three, rook five, queen nine; the king is not counted.', 1, NULL, 0, 75, N'A0000000-0000-0000-0000-000000000047', 36, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002337', 3, N'What is a gambit, and name one?', N'An opening that offers material for time or position; the Queen''s Gambit is the best known.', 1, N'FIDE Laws of Chess', 0, 90, N'A0000000-0000-0000-0000-000000000047', 37, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002338', 3, N'What is the fastest possible checkmate, and what is it called?', N'Two moves, known as fool''s mate.', 1, N'FIDE Laws of Chess', 0, 105, N'A0000000-0000-0000-0000-000000000047', 38, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002339', 3, N'What is the Sicilian Defence, and why is it popular?', N'The reply c5 to e4, which fights for the centre asymmetrically and plays for a win with black.', 1, NULL, 1, 120, N'A0000000-0000-0000-0000-000000000047', 39, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002340', 3, N'What is algebraic notation, and how is a square named?', N'The standard notation naming each square by file letter and rank number, such as e4.', 1, N'FIDE Laws of Chess', 0, 60, N'A0000000-0000-0000-0000-000000000047', 40, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002341', 3, N'What does the symbol "!" mean in notation, and what does "?" mean?', N'A good move and a bad one; doubled they mean brilliant and blundering.', 1, N'FIDE Laws of Chess', 0, 75, N'A0000000-0000-0000-0000-000000000047', 41, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002342', 3, N'What is the difference between a bishop pair and opposite-coloured bishops in the endgame?', N'The pair covers both colours and is a lasting advantage; opposite colours often make a draw likelier because neither can attack the other''s squares.', 1, NULL, 0, 90, N'A0000000-0000-0000-0000-000000000047', 42, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002343', 3, N'What is the touch-move rule?', N'A touched piece must be moved if it has a legal move, and a touched enemy piece must be captured if legally possible.', 1, N'FIDE Laws of Chess', 0, 105, N'A0000000-0000-0000-0000-000000000047', 43, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002344', 3, N'What is the difference between blitz, rapid and classical time controls?', N'Blitz gives a few minutes each, rapid gives tens of minutes, and classical gives an hour or more with increments.', 1, N'FIDE Laws of Chess', 0, 120, N'A0000000-0000-0000-0000-000000000047', 44, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002345', 1, N'Play one game at a slow time control and write down your moves.', NULL, 1, NULL, 0, 180, N'A0000000-0000-0000-0000-000000000047', 45, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002346', 1, N'Solve ten mate-in-two puzzles without moving the pieces.', NULL, 1, N'FIDE Laws of Chess', 0, 240, N'A0000000-0000-0000-0000-000000000047', 46, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002347', 1, N'Set up a king and pawn endgame and play it out against yourself.', NULL, 1, N'FIDE Laws of Chess', 0, 300, N'A0000000-0000-0000-0000-000000000047', 47, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002348', 1, N'Watch a commentated grandmaster game and pause to guess each move.', NULL, 1, NULL, 0, 360, N'A0000000-0000-0000-0000-000000000047', 48, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002349', 1, N'Learn the first five moves of one opening for white and one for black.', NULL, 1, N'FIDE Laws of Chess', 0, 420, N'A0000000-0000-0000-0000-000000000047', 49, '2026-02-28T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002350', 1, N'Explain to someone how the knight moves and why it is unusual.', NULL, 1, N'FIDE Laws of Chess', 0, 180, N'A0000000-0000-0000-0000-000000000047', 50, '2026-02-28T09:00:00', 1, '2026-07-13T09:00:00');

