    (N'B0000000-0000-0000-0000-000000002359', 4, N'What is the setting that corrects that cast called?', NULL, 1, NULL, 0, 20, N'A0000000-0000-0000-0000-000000000048', 9, '2026-03-01T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002360', 4, N'What is the unit of colour temperature?', NULL, 1, N'Understanding Exposure', 0, 25, N'A0000000-0000-0000-0000-000000000048', 10, '2026-03-01T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002361', 4, N'What is the raw uncompressed image file generally called?', NULL, 1, N'Understanding Exposure', 0, 30, N'A0000000-0000-0000-0000-000000000048', 11, '2026-03-01T09:00:00', 0, NULL),
