VALUES
    (N'B0000000-0000-0000-0000-000000002401', 4, N'What is the term for a plant that lives one season?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 20, N'A0000000-0000-0000-0000-000000000049', 1, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002402', 4, N'What is the term for a plant that lives two seasons?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 25, N'A0000000-0000-0000-0000-000000000049', 2, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002403', 4, N'What is the term for a plant that lives many years?', NULL, 1, NULL, 0, 30, N'A0000000-0000-0000-0000-000000000049', 3, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002404', 4, N'What is the term for cutting back a plant to shape it?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 15, N'A0000000-0000-0000-0000-000000000049', 4, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002405', 4, N'What is the term for removing spent flowers?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 20, N'A0000000-0000-0000-0000-000000000049', 5, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002406', 4, N'What is a layer of material spread on soil to hold moisture called?', NULL, 1, NULL, 0, 25, N'A0000000-0000-0000-0000-000000000049', 6, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002407', 4, N'What is decomposed organic matter used to enrich soil called?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 30, N'A0000000-0000-0000-0000-000000000049', 7, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002408', 4, N'What is the measure of soil acidity called?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 15, N'A0000000-0000-0000-0000-000000000049', 8, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002409', 4, N'What pH range do most garden plants prefer?', NULL, 1, NULL, 0, 20, N'A0000000-0000-0000-0000-000000000049', 9, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002410', 4, N'What is the process by which plants make sugar from light called?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 25, N'A0000000-0000-0000-0000-000000000049', 10, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002411', 4, N'What is the loss of water through leaves called?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 30, N'A0000000-0000-0000-0000-000000000049', 11, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002412', 4, N'What is a plant grown from a piece of a parent plant called?', NULL, 1, NULL, 0, 15, N'A0000000-0000-0000-0000-000000000049', 12, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002413', 4, N'What is joining a shoot of one plant onto the roots of another called?', NULL, 1, N'RHS Encyclopedia of Gardening', 1, 20, N'A0000000-0000-0000-0000-000000000049', 13, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002414', 4, N'What is moving a seedling to a larger pot called?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 25, N'A0000000-0000-0000-0000-000000000049', 14, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002415', 4, N'What is hardening off?', NULL, 1, NULL, 0, 30, N'A0000000-0000-0000-0000-000000000049', 15, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002416', 4, N'What is the term for soil that drains freely and is gritty?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 15, N'A0000000-0000-0000-0000-000000000049', 16, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002417', 4, N'What is the term for soil that holds water and packs hard?', NULL, 0, N'RHS Encyclopedia of Gardening', 0, 20, N'A0000000-0000-0000-0000-000000000049', 17, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002418', 4, N'What is the ideal balanced garden soil called?', NULL, 1, NULL, 0, 25, N'A0000000-0000-0000-0000-000000000049', 18, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002419', 4, N'What do the three numbers on fertiliser packaging stand for?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 30, N'A0000000-0000-0000-0000-000000000049', 19, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002420', 4, N'Which nutrient mainly drives leaf growth?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 15, N'A0000000-0000-0000-0000-000000000049', 20, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002421', 4, N'Which nutrient mainly supports roots?', NULL, 1, NULL, 0, 20, N'A0000000-0000-0000-0000-000000000049', 21, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002422', 4, N'Which nutrient mainly supports flowers and fruit?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 25, N'A0000000-0000-0000-0000-000000000049', 22, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002423', 4, N'What is the commonest cause of houseplant death?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 30, N'A0000000-0000-0000-0000-000000000049', 23, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002424', 4, N'What is a plant that stores water in its leaves called?', NULL, 1, NULL, 0, 15, N'A0000000-0000-0000-0000-000000000049', 24, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002425', 4, N'What is a plant that grows on another without harming it called?', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 20, N'A0000000-0000-0000-0000-000000000049', 25, '2026-03-02T09:00:00', 1, '2026-07-15T09:00:00'),
    (N'B0000000-0000-0000-0000-000000002426', 2, N'Explain why overwatering kills more houseplants than underwatering.', N'Waterlogged compost drives out air, the roots suffocate and rot, and the plant then cannot take up water at all, which looks like drought.', 1, N'RHS Encyclopedia of Gardening', 1, 75, N'A0000000-0000-0000-0000-000000000049', 26, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002427', 2, N'Explain how to tell when a potted plant needs water.', N'Push a finger into the compost; water when the top few centimetres are dry, and check the weight of the pot rather than the surface.', 1, NULL, 0, 90, N'A0000000-0000-0000-0000-000000000049', 27, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002428', 2, N'Explain what photosynthesis needs and what it produces.', N'Light, water and carbon dioxide, producing sugar and oxygen.', 1, N'RHS Encyclopedia of Gardening', 0, 45, N'A0000000-0000-0000-0000-000000000049', 28, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002429', 2, N'Explain what mulch does for a bed.', N'It keeps moisture in, suppresses weeds, moderates soil temperature and feeds the soil as it breaks down.', 1, N'RHS Encyclopedia of Gardening', 0, 60, N'A0000000-0000-0000-0000-000000000049', 29, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002430', 2, N'Explain why pruning encourages growth rather than reducing it.', N'Removing a growing tip releases the buds below from dominance, so the plant branches out.', 1, NULL, 0, 75, N'A0000000-0000-0000-0000-000000000049', 30, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002431', 2, N'Explain what a plant''s hardiness rating tells you.', N'The lowest temperature it reliably survives, which decides whether it can stay outside through your winter.', 1, N'RHS Encyclopedia of Gardening', 0, 90, N'A0000000-0000-0000-0000-000000000049', 31, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002432', 2, N'Explain the difference between full sun, partial shade and full shade.', N'Six hours or more of direct sun, roughly three to six, and less than three.', 1, N'RHS Encyclopedia of Gardening', 0, 45, N'A0000000-0000-0000-0000-000000000049', 32, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002433', 2, N'Explain why leaves turn yellow, and name three possible causes.', N'Overwatering, a nitrogen shortage or too little light; the pattern of yellowing and which leaves are affected tell them apart.', 1, NULL, 0, 60, N'A0000000-0000-0000-0000-000000000049', 33, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002434', 2, N'Explain what companion planting claims to do.', N'Growing certain plants together to deter pests, attract pollinators or improve growth.', 0, N'RHS Encyclopedia of Gardening', 0, 75, N'A0000000-0000-0000-0000-000000000049', 34, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002435', 2, N'Explain how compost is made and what it needs.', N'Alternate green nitrogen-rich and brown carbon-rich material, keep it moist and aired, and let microbes and heat break it down over months.', 1, N'RHS Encyclopedia of Gardening', 0, 90, N'A0000000-0000-0000-0000-000000000049', 35, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002436', 3, N'What does the N in NPK stand for, and what does it do?', N'Nitrogen, which drives leafy green growth.', 1, NULL, 0, 75, N'A0000000-0000-0000-0000-000000000049', 36, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002437', 3, N'What is chlorosis, and what usually causes it?', N'Yellowing between the leaf veins, usually a shortage of iron or magnesium, often because the soil is too alkaline.', 1, N'RHS Encyclopedia of Gardening', 0, 90, N'A0000000-0000-0000-0000-000000000049', 37, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002438', 3, N'What is root-bound, and how do you fix it?', N'Roots have filled the pot and circle the inside; tease them out and pot on into a slightly larger container.', 1, N'RHS Encyclopedia of Gardening', 0, 105, N'A0000000-0000-0000-0000-000000000049', 38, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002439', 3, N'What is the difference between potting compost and garden soil?', N'Potting compost is sterile, light and free-draining and made for containers; garden soil compacts and carries weed seeds and disease.', 1, NULL, 1, 120, N'A0000000-0000-0000-0000-000000000049', 39, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002440', 3, N'What are the commonest houseplant pests, and how are they spotted?', N'Spider mites, mealybugs, scale and fungus gnats; look under leaves, in leaf joints and at the compost surface.', 1, N'RHS Encyclopedia of Gardening', 0, 60, N'A0000000-0000-0000-0000-000000000049', 40, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002441', 3, N'Which houseplant is famous for tolerating neglect and low light?', N'The snake plant, also called sansevieria.', 1, N'RHS Encyclopedia of Gardening', 0, 75, N'A0000000-0000-0000-0000-000000000049', 41, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002442', 3, N'What is bottom watering, and when is it useful?', N'Standing the pot in water so it draws up from below; useful for plants that dislike wet leaves or compost that has dried hard.', 1, NULL, 0, 90, N'A0000000-0000-0000-0000-000000000049', 42, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002443', 3, N'What is dormancy, and how should watering change during it?', N'The rest period in winter when growth stops; water much less and do not feed.', 1, N'RHS Encyclopedia of Gardening', 0, 105, N'A0000000-0000-0000-0000-000000000049', 43, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002444', 3, N'What does deadheading achieve?', N'It stops the plant setting seed, so it keeps flowering for longer.', 1, N'RHS Encyclopedia of Gardening', 0, 120, N'A0000000-0000-0000-0000-000000000049', 44, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002445', 1, N'Repot one plant that has outgrown its container.', NULL, 1, NULL, 0, 180, N'A0000000-0000-0000-0000-000000000049', 45, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002446', 1, N'Take a cutting from a houseplant and root it in water.', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 240, N'A0000000-0000-0000-0000-000000000049', 46, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002447', 1, N'Test the pH of your garden soil with a kit.', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 300, N'A0000000-0000-0000-0000-000000000049', 47, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002448', 1, N'Draw a plan of a bed and mark what has sun and what has shade.', NULL, 1, NULL, 0, 360, N'A0000000-0000-0000-0000-000000000049', 48, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002449', 1, N'Start a compost heap or bin and turn it after a month.', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 420, N'A0000000-0000-0000-0000-000000000049', 49, '2026-03-02T09:00:00', 0, NULL),
    (N'B0000000-0000-0000-0000-000000002450', 1, N'Explain to someone why overwatering is worse than underwatering.', NULL, 1, N'RHS Encyclopedia of Gardening', 0, 180, N'A0000000-0000-0000-0000-000000000049', 50, '2026-03-02T09:00:00', 1, '2026-07-15T09:00:00');

